/* эмодзи → id иконки. Канонический `e` и все `syn` ведут на одну иконку. */
const BOS_EMOJI_GLYPH = (function () {
  var m = {};
  BOS_GLYPH_ORDER.forEach(function (id) {
    var g = BOS_GLYPHS[id];
    if (!g) return;
    if (g.e && !m[g.e]) m[g.e] = id;
    (g.syn || []).forEach(function (s) { if (s && !m[s]) m[s] = id; });
  });
  return m;
})();

/* Какую иконку показать для сохранённого значка. null → показываем эмодзи как раньше.
   Терпим к тому, что облако РЕЖЕТ строку: extra-kit пишет slice(0,4), публичная
   статистика slice(0,8) — последовательность «🏃‍♀️» приезжает обрубком «🏃‍♀».
   Поэтому пробуем по очереди: как есть → без хвоста → без VS16 и тона кожи → первый символ. */
function bosGlyphIdFor(val) {
  if (!BOS_GLYPHS_ON || typeof val !== "string") return null;
  var v = val.trim();
  if (!v) return null;
  if (BOS_EMOJI_GLYPH[v]) return BOS_EMOJI_GLYPH[v];
  var cut = v.replace(/[\uFE0F\u200D]+$/, "");
  if (BOS_EMOJI_GLYPH[cut]) return BOS_EMOJI_GLYPH[cut];
  var flat = v.replace(/[\uFE0F\u{1F3FB}-\u{1F3FF}]/gu, "");
  if (BOS_EMOJI_GLYPH[flat]) return BOS_EMOJI_GLYPH[flat];
  var head = flat.split("\u200D")[0];
  if (head && BOS_EMOJI_GLYPH[head]) return BOS_EMOJI_GLYPH[head];
  return null;
}

/* Эмодзи, который УЙДЁТ В ДАННЫЕ при выборе иконки id. Единственный канал записи. */
function bosGlyphEmoji(id) { var g = BOS_GLYPHS[id]; return (g && g.e) || "\u2728"; }

/* Сама иконка. size — сторона квадрата в px (как fontSize у эмодзи).
   color не задан → currentColor, цвет наследуется от родителя, как у текста. */
function BosGlyph({ id, size = 20, color, style, className }) {
  const g = BOS_GLYPHS[id];
  if (!g) return null;
  return (
    <svg width={size} height={size} viewBox="0 0 256 256" fill={color || "currentColor"}
      aria-hidden="true" className={className} style={{ display: "block", flexShrink: 0, ...style }}>{g.s}</svg>
  );
}

